# -*- coding: utf-8 -*-
"""Base IEEE OUI (préfixe MAC -> constructeur), source : paquet npm oui-data 2.1.42 (BSD-2-Clause)."""
import base64, zlib
_Z = ""
def load():
    raw = zlib.decompress(base64.b64decode(_Z)).decode()
    names, pairs = raw.split("\x00")
    names = names.split("\n")
    return {p[:6]: names[int(p[6:], 16)] for p in pairs.split(",")}
